import assert from 'node:assert/strict';
import crypto from 'node:crypto';
import fs from 'node:fs';
import zlib from 'node:zlib';

const SITE_DIR='governance/forecast-evidence/BKL031-F7-PROTECTED-SITE-RUN-35255829165';
const LEGACY_DIR='governance/forecast-evidence/BKL031-F7-RUN-35243920092';
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const decode=p=>zlib.gunzipSync(Buffer.from(fs.readFileSync(p,'utf8').trim(),'base64'));
const json=p=>JSON.parse(fs.readFileSync(p,'utf8'));

const manifest=json(`${SITE_DIR}/evidence-manifest.json`);
const request=json(`${SITE_DIR}/request-plan.json`);
const summary=json(`${SITE_DIR}/summary.json`);
const auth=json('governance/forecast-evidence/BKL031-F7-PROTECTED-SITE-PROVIDER-REQUEST-AUTH-001.json');
const privacy=json('governance/forecast-evidence/BKL031-F7-PROTECTED-SITE-OUTBOUND-PRIVACY-AUTH-001.json');
const receipt=json('governance/forecast-evidence/BKL031-F7-PROTECTED-SITE-PROVIDER-REQUEST-RECEIPT-001.json');
const site=json('governance/site-authority/site-records/DSG-SITE-RECORD-MANCIANO-001.approved.json');
const normalizedBytes=decode(`${SITE_DIR}/normalized-supply.json.gz.b64`);
const supply=JSON.parse(normalizedBytes.toString('utf8'));
const projectionPath='docs/data/observation-planner-forecast-f7-site-projection.json';
const projectionText=fs.readFileSync(projectionPath,'utf8');
const projection=JSON.parse(projectionText);

assert.equal(manifest.workflowRunId,35255829165);
assert.equal(manifest.workflowHeadSha,'2c46ca8be59c9ea8245fa03de71e936249c52a1b');
assert.equal(manifest.artifactId,10512359912);
assert.equal(manifest.artifactDigest,'sha256:9c2c58f4f4d63bced1110b94de4463f17eb0a2bc14362c22bb3435cbce9455ef');
assert.equal(manifest.rawResponseSha256,'1d66a83464c946b203ef60730a993acb913a9ee12bbf5ec0ab0839bff54b3046');
assert.equal(sha(normalizedBytes),manifest.normalizedSupplySha256);
assert.equal(manifest.normalizedSupplySha256,'1df1894917962b29f83c4f24cbeb6572f71371e3b0877cdd4cf04833395577c8');
assert.equal(sha(Buffer.from(fs.readFileSync(`${SITE_DIR}/request-plan.json`,'utf8'))),manifest.requestPlanSha256);
assert.equal(sha(Buffer.from(fs.readFileSync(`${SITE_DIR}/summary.json`,'utf8'))),manifest.summarySha256);
assert.equal(fs.readFileSync(`${SITE_DIR}/raw-response.sha256`,'utf8').trim(),manifest.rawResponseSha256);

assert.equal(auth.authorizationId,'BKL031-F7-PROTECTED-SITE-PROVIDER-REQUEST-AUTH-001');
assert.equal(auth.status,'AUTHORIZED');
assert.equal(auth.maxProviderRequests,1);
assert.equal(auth.requestBudgetState,'0/1_AUTHORIZED');
assert.equal(auth.protectedSiteUsed,true);
assert.equal(auth.recurringTraffic,false);
assert.equal(auth.productionUse,false);
assert.equal(auth.privacyDecisionRef,'governance/forecast-evidence/BKL031-F7-PROTECTED-SITE-OUTBOUND-PRIVACY-AUTH-001.json');
assert.equal(privacy.status,'AUTHORIZED');
assert.equal(privacy.permittedRecipient.host,'single-runs-api.open-meteo.com');
assert.equal(privacy.coordinatePolicy.source,'GOVERNED_APPROVED_SITE_RECORD');
assert.equal(privacy.coordinatePolicy.use,'SERVER_SIDE_PROVIDER_REQUEST_ONLY');
assert.equal(privacy.coordinatePolicy.logCoordinates,false);
assert.equal(privacy.coordinatePolicy.persistCoordinatesInForecastEvidence,false);
assert.equal(privacy.coordinatePolicy.publishCoordinates,false);
assert.equal(receipt.authorizationId,auth.authorizationId);
assert.equal(receipt.workflowConclusion,'SUCCESS');
assert.equal(receipt.providerRequestCount,1);
assert.equal(receipt.budgetState,'1/1_EXHAUSTED');
assert.equal(receipt.additionalProviderRequestsAuthorized,false);

assert.equal(site.lifecycle.state,'APPROVED');
assert.equal(site.lifecycle.eligibleForResolution,true);
assert.equal(site.sitePayload.siteRecordId,'DSG-SITE-RECORD-MANCIANO-001');
assert.equal(site.sitePayload.classification,'PROTECTED_EXACT_SITE');
assert.equal(site.sitePayload.scope,'OBSERVATION_PLANNER_READ_ONLY_SITE_AUTHORITY');
assert.equal(site.sitePayload.publicationPolicy.exactCoordinates,'PROHIBITED');
assert.equal(site.sitePayload.publicationPolicy.elevation,'PROHIBITED');

assert.equal(request.expectedHost,'single-runs-api.open-meteo.com');
assert.equal(request.maxRequestsThisGate,1);
assert.equal(request.runInitialisationUtc,'2026-09-17T12:00Z');
assert.equal(request.location.classification,'PROTECTED_EXACT_SITE');
assert.equal(request.protectedSiteUsed,true);
assert.equal(request.location.coordinatesPersisted,false);
assert.equal(request.location.coordinatesPublished,false);
assert.ok(!Object.hasOwn(request.location,'latitudeDeg')&&!Object.hasOwn(request.location,'longitudeDeg')&&!Object.hasOwn(request.location,'elevationM'));

assert.equal(supply.schemaVersion,'1.1');
assert.equal(supply.contractType,'BKL031_F7_FORECAST_RUNTIME_SUPPLY');
assert.equal(supply.environment,'EVALUATION');
assert.equal(supply.authority,'NONE');
assert.equal(supply.authorizationId,auth.authorizationId);
assert.equal(supply.privacyDecisionId,privacy.decisionId);
assert.equal(supply.providerId,'OPEN_METEO');
assert.equal(supply.upstreamAuthorityId,'ITALIAMETEO_ARPAE');
assert.equal(supply.modelId,'italia_meteo_arpae_icon_2i');
assert.equal(supply.runInitialisationUtc,'2026-09-17T12:00Z');
assert.equal(supply.location.classification,'PROTECTED_EXACT_SITE');
assert.equal(supply.location.protectedSiteUsed,true);
assert.equal(supply.location.coordinatesPersisted,false);
assert.equal(supply.location.coordinatesPublished,false);
assert.equal(supply.freshness.maxRunAgeHours,18);
assert.equal(supply.freshness.state,'FRESH');
assert.ok(supply.freshness.runAgeHoursAtRetrieval>=0&&supply.freshness.runAgeHoursAtRetrieval<=18);
assert.equal(supply.requestAccounting.maxProviderRequests,1);
assert.equal(supply.requestAccounting.requestOrdinal,1);
assert.equal(supply.requestAccounting.budgetState,'1/1_EXHAUSTED');
assert.equal(supply.series.rawInstantCount,72);
assert.equal(supply.series.acceptedInstantCount,71);
assert.equal(supply.series.excludedInstantCount,1);
assert.equal(supply.series.futureAcceptedInstantCount,66);
assert.equal(supply.series.imputedValueCount,0);
assert.equal(supply.series.excluded[0].instantUtc,'2026-09-17T12:00Z');
assert.deepEqual(supply.series.excluded[0].variables,['precipitation']);
assert.equal(supply.availabilityState,'DEGRADED');
assert.equal(supply.boundaries.recurringTraffic,false);
assert.equal(supply.boundaries.productionRuntimeActivated,false);
assert.equal(supply.boundaries.readinessAuthority,false);
assert.equal(supply.boundaries.schedulingAuthority,false);
assert.equal(supply.boundaries.automaticTargetSelection,false);
assert.equal(supply.boundaries.commandAuthority,'NONE');
assert.equal(supply.boundaries.safetyAuthority,'LOCAL_PHYSICAL_INTERLOCKS');

assert.equal(summary.budgetState,'1/1_EXHAUSTED');
assert.equal(summary.rawSha256,manifest.rawResponseSha256);
assert.equal(summary.acceptedInstantCount,71);
assert.equal(summary.futureAcceptedInstantCount,66);
assert.equal(summary.protectedSiteUsed,true);
assert.equal(summary.coordinatesPersisted,false);
assert.equal(summary.coordinatesPublished,false);

const legacySummary=json(`${LEGACY_DIR}/summary.json`);
assert.equal(legacySummary.budgetState,'1/1_EXHAUSTED');
assert.equal(legacySummary.protectedSiteUsed,false);
assert.equal(legacySummary.futureAcceptedInstantCount,67);

assert.equal(projection.schemaVersion,'1.0');
assert.equal(projection.projectionType,'BKL031_F7_PROTECTED_SITE_SANITIZED_FORECAST_PROJECTION');
assert.equal(projection.environment,'EVALUATION');
assert.equal(projection.authority,'NONE');
assert.equal(projection.publicationState,'READ_ONLY');
assert.equal(projection.site.publicLabel,'Manciano (GR), Italia');
assert.equal(projection.site.coordinateDisclosure,'PROHIBITED');
assert.equal(projection.sourceEvidence.workflowRunId,35255829165);
assert.equal(projection.sourceEvidence.acceptedHourlyInstantCount,71);
assert.equal(projection.sourceEvidence.excludedHourlyInstantCount,1);
assert.equal(projection.sourceEvidence.imputedValueCount,0);
assert.equal(projection.model.freshnessState,'FRESH');
assert.equal(projection.model.maxRunAgeHours,18);
assert.equal(projection.forecast.hourly.length,71);
assert.equal(projection.forecast.availabilityState,'DEGRADED');
assert.equal(projection.boundaries.readinessAuthority,false);
assert.equal(projection.boundaries.commandAuthority,'NONE');
for(const forbiddenKey of ['latitudeDeg','longitudeDeg','latitude','longitude','elevationM','returnedGrid','rawResponseSha256','rawSha256','siteAuthorityRef','rawRequestUrl','requestUrl']) assert.ok(!projectionText.includes(`\"${forbiddenKey}\"`),`public projection contains forbidden key ${forbiddenKey}`);
for(const protectedCoordinate of [site.sitePayload.geodesy.latitudeDeg,site.sitePayload.geodesy.longitudeDeg]) assert.ok(!projectionText.includes(String(protectedCoordinate)),'public projection contains a protected coordinate literal');

const portal=fs.readFileSync('docs/observation-planner/index.md','utf8');
const consumer=fs.readFileSync('docs/javascripts/observation-planner-forecast-f7-site.js','utf8');
assert.ok(portal.includes('data-observation-planner-site-forecast'));
assert.ok(portal.includes('forecast reale'));
assert.ok(consumer.includes("currentRunAgeHours"));
assert.ok(consumer.includes("Forecast F7 non più fresco"));
assert.ok(consumer.includes("../data/observation-planner-forecast-f7-site-projection.json"));
for(const protectedCoordinate of [site.sitePayload.geodesy.latitudeDeg,site.sitePayload.geodesy.longitudeDeg]) assert.ok(!portal.includes(String(protectedCoordinate))&&!consumer.includes(String(protectedCoordinate)),'public portal contains a protected coordinate literal');

const runtimeSchema=json('schemas/observation-planner-forecast-runtime-supply-f7.schema.json');
assert.equal(runtimeSchema.properties.schemaVersion.const,'1.1');
assert.equal(runtimeSchema.properties.location.properties.classification.const,'PROTECTED_EXACT_SITE');
assert.equal(runtimeSchema.properties.location.properties.protectedSiteUsed.const,true);
const projectionSchema=json('schemas/observation-planner-forecast-projection-f7-site.schema.json');
assert.equal(projectionSchema.properties.projectionType.const,'BKL031_F7_PROTECTED_SITE_SANITIZED_FORECAST_PROJECTION');

assert.ok(!fs.existsSync('.github/scripts/observation-planner-forecast-f7-acquire.mjs'),'consumed generalized F7 acquisition script must be removed.');
assert.ok(!fs.existsSync('.github/workflows/bkl-031-f7-one-request-acquisition.yml'),'consumed generalized F7 acquisition workflow must be removed.');
assert.ok(!fs.existsSync('.github/scripts/observation-planner-forecast-f7-protected-site-acquire.mjs'),'consumed protected-site F7 acquisition script must be removed.');
assert.ok(!fs.existsSync('.github/workflows/bkl-031-f7-protected-site-one-request.yml'),'consumed protected-site F7 acquisition workflow must be removed.');

const doc=fs.readFileSync('docs/architecture/scientific-assets/BKL-031-F7-Fresh-Forecast-Supply-and-Runtime-Boundary.md','utf8');
for(const marker of ['ACCEPTED — POST-MERGE VERIFIED','35255829165','71 complete positions','66 future accepted instants','does not close BKL-031']) assert.ok(doc.includes(marker),`F7 document missing ${marker}`);
const validation=fs.readFileSync('docs/architecture/validation/BKL-031-F7-Fresh-Forecast-Supply-Evidence-2026-09-17.md','utf8');
assert.ok(validation.includes('PROTECTED-SITE EVIDENCE ACQUIRED')&&validation.includes('1/1_EXHAUSTED')&&validation.includes('DEGRADED')&&validation.includes('FRESH'));
const roadmap=json('.github/roadmap/roadmap-source.json');
assert.ok(['BKL-036 Observatory Health Score','BKL-036-F5 Live Read-Only Health Score','AP-015','BKL-033','BKL-034','BKL-034-F2','BKL-042','BKL-043'].includes(roadmap.nextMilestone));
const acceptance=fs.readFileSync('docs/project/BKL-031-F7-FRESH-FORECAST-SUPPLY-ACCEPTANCE-2026-09-17.md','utf8');
for(const marker of ['ACCEPTED — POST-MERGE VERIFIED','000fc81558060b45e71b9f1a69122249b6a5fe8e','59a1d690406d733b6e61e64220f84cef9b6fb1a2','10/10 successful','1/1_EXHAUSTED']) assert.ok(acceptance.includes(marker),`F7 acceptance missing ${marker}`);

console.log('BKL-031 F7 verified: protected-site real forecast, 72 raw / 71 accepted / 1 excluded / 66 future, zero imputation, sanitized public projection, exhausted one-shot path removed.');
